import os
import subprocess
import re
import zipfile

subjects = {
    "LLM": ["LLM", "large language model", "GPT", "transformer", "attention mechanism", "neural network", "natural language processing", "pre-training", "pretraining"],
    "trapped_ion_and_qc": ["trapped ion", "quantum computing", "qubit", "ion trap", "quantum gate", "quantum information", "Rabi", "Lamb-Dicke"],
    "black_hole": ["black hole", "event horizon", "hawking radiation", "Schwarzschild", "general relativity", "gravitational"],
    "DNA": ["DNA", "genome", "sequencing", "nucleotide", "gene", "mutation", "biological", "genomics"],
    "music_history": ["music history", "composer", "symphony", "baroque", "classical music", "jazz", "opera", "renaissance music"]
}

source_dir = "papers/all"
dest_base = "papers"

# Since some files might have been moved already, let's look in the destination folders too if we need to re-evaluate, 
# but the prompt says organize them into 5 folders. 
# I'll just check what's left in papers/all and also what was moved to music_history by mistake.

dirs_to_check = [source_dir, os.path.join(dest_base, "music_history")]

for d in dirs_to_check:
    if not os.path.exists(d):
        continue
    files = os.listdir(d)
    for filename in files:
        filepath = os.path.join(d, filename)
        if os.path.isdir(filepath):
            continue

        text = ""
        if filename.endswith(".pdf"):
            try:
                result = subprocess.run(["pdftotext", "-f", "1", "-l", "2", filepath, "-"], capture_output=True, text=True)
                text = result.stdout
            except Exception as e:
                print(f"Error processing PDF {filename}: {e}")
        elif filename.endswith(".docx") or filename.endswith(".pptx"):
            try:
                with zipfile.ZipFile(filepath, 'r') as z:
                    if filename.endswith(".docx"):
                        content = z.read("word/document.xml").decode('utf-8')
                    else:
                        # For pptx, just read all slide xmls and concatenate
                        content = ""
                        for name in z.namelist():
                            if name.startswith("ppt/slides/slide"):
                                content += z.read(name).decode('utf-8')
                    text = re.sub(r'<[^>]*>', ' ', content)
            except Exception as e:
                print(f"Error processing docx/pptx {filename}: {e}")

        text_lower = text.lower()
        found_subject = None

        for subject, keywords in subjects.items():
            if any(kw.lower() in text_lower for kw in keywords):
                found_subject = subject
                break

        if not found_subject:
            found_subject = "music_history"

        dest_dir = os.path.join(dest_base, found_subject)
        dest_path = os.path.join(dest_dir, filename)

        if filepath != dest_path:
            print(f"Moving {filename} from {d} to {found_subject}")
            if os.path.exists(dest_path):
                # If it already exists in the right place, just remove the old one if it's different
                if filepath != dest_path:
                    os.remove(filepath)
            else:
                os.rename(filepath, dest_path)

